--
-- Table structure for table `ai_message`
--

DROP TABLE IF EXISTS `ai_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_message` (
  `id` bigint NOT NULL COMMENT '消息ID',
  `conversation_id` bigint NOT NULL COMMENT '会话ID',
  `user_id` bigint NOT NULL COMMENT '所属用户ID，用于所有权校验',
  `request_id` varchar(64) NOT NULL COMMENT '服务端轮次标识；历史数据使用legacy前缀',
  `seq` bigint NOT NULL COMMENT '会话内全局递增消息序号',
  `role` varchar(16) NOT NULL COMMENT '消息角色：user、assistant、tool',
  `kind` varchar(32) NOT NULL COMMENT 'USER_INPUT、ASSISTANT_STEP、TOOL_RESULT、ASSISTANT_FINAL',
  `content` longtext NOT NULL COMMENT 'Jackson完整框架消息JSON原文，避免原生JSON数字精度转换',
  `run_status` varchar(32) DEFAULT NULL COMMENT '轮次状态，仅USER_INPUT使用，不改写消息原文',
  `error_code` varchar(80) DEFAULT NULL COMMENT '轮次失败原因编码，仅USER_INPUT使用',
  `history_summary` text COMMENT '最终回复历史导航摘要，未生成或失败为NULL，不替代原文',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常，1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_message_sequence` (`conversation_id`,`seq`),
  KEY `idx_ai_message_user` (`user_id`,`deleted`),
  KEY `idx_ai_message_history` (`conversation_id`,`deleted`,`kind`,`seq`),
  KEY `idx_ai_message_request` (`conversation_id`,`request_id`,`seq`),
  KEY `idx_ai_message_summary_scan` (`kind`,`deleted`,`id`),
  CONSTRAINT `chk_ai_message_content` CHECK (json_valid(`content`)),
  CONSTRAINT `chk_ai_message_history_summary` CHECK (((`history_summary` is null) or ((`kind` = _utf8mb4'ASSISTANT_FINAL') and (char_length(`history_summary`) between 1 and 500))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI经营助手消息表';
/*!40101 SET character_set_client = @saved_cs_client */;

