  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常，1删除',
  PRIMARY KEY (`id`),
  KEY `idx_ai_node_experience_query` (`node_code`,`status`,`deleted`,`effective_from`)
