INSERT INTO `ai_node_working_memory` VALUES (2110785523665653762,2110785523187503105,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 01:31:00','2026-10-16 01:31:00',0),(2110785597346992131,2110785523187503105,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量分布与排名\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天（从2026-09-16 00:00:00到2026-10-16 01:31:00）销售出库记录中的仓库、商品和销售数量，排除已作废或冲销的单据，按仓库和商品返回明细。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的查询结果，按仓库汇总各商品销量，计算各仓库总销量、商品销量排名和销量占比，识别各仓库销量最高和最低的商品，并生成仓库销量对比及重点商品图表。\"}]}',NULL,'2026-10-16 01:31:17','2026-10-16 01:31:17',0),(2110796466155978754,2110796465220648961,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:14:28','2026-10-16 02:14:28',0),(2110796504844238850,2110796465220648961,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询当前时间往前30天内，按仓库和商品汇总的销售数量，返回仓库、商品、销量等字段，并排除作废、冲红等无效销售记录。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的查询结果，统计各仓库销量合计、商品销量排名，并进行跨仓库对比分析。\"}]}',NULL,'2026-10-16 02:14:38','2026-10-16 02:14:38',0),(2110797025151848451,2110797024304599041,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:16:42','2026-10-16 02:16:42',0),(2110797057028558850,2110797024304599041,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天各仓库的销售出库记录，按仓库和商品汇总销售数量，统计口径为确认出库的销售数量，包含仓库、商品、销售数量字段。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于上一步查询结果，计算各仓库销量合计，识别各仓库热销商品，并对仓库销量进行排序和可视化分析。\"}]}',NULL,'2026-10-16 02:16:49','2026-10-16 02:16:49',0),(2110797097864302595,2110797097671364609,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:16:59','2026-10-16 02:16:59',0),(2110797158992089091,2110797097671364609,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量\",\"needs_clarification\":true,\"clarification_questions\":[{\"id\":\"sales_metric\",\"question\":\"销量使用哪个统计口径？\",\"options\":[\"销售出库数量\",\"销售订单数量\",\"实际出库数量\",\"净销量（扣除退货）\"]}],\"steps\":[]}',NULL,'2026-10-16 02:17:14','2026-10-16 02:17:14',0),(2110797787277852675,2110797786447380482,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:19:43','2026-10-16 02:19:43',0),(2110797828235231233,2110797786447380482,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询以当前时间2026-10-16为基准的最近30天内，各仓库已完成且未作废的销售出库记录，按仓库和商品汇总销售数量及销售金额。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的查询结果，分析各仓库的销量总量、销量占比，并识别各仓库销量靠前的商品，生成仓库销量排名和TOP商品分析。\"}]}',NULL,'2026-10-16 02:19:53','2026-10-16 02:19:53',0),(2110798116602056705,2110798115863859202,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:21:02','2026-10-16 02:21:02',0),(2110798185971650562,2110798115863859202,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库各商品的销量情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天各仓库各商品的销量，按仓库和商品维度汇总销售出库数量，并关联获取仓库名称、商品名称等必要维度信息。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1查询结果，计算各仓库的总销量及销量占比，对各仓库进行销量对比，并识别每个仓库销量最高的商品。\"},{\"step\":3,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1查询结果，分析全部商品的销量排名和集中度，识别高销量商品及销量异常情况，输出可视化图表。\"}]}',NULL,'2026-10-16 02:21:18','2026-10-16 02:21:18',0),(2110798187880058881,2110798187695509505,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:21:19','2026-10-16 02:21:19',0),(2110798228820660225,2110798187695509505,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析计划\",\"objective\":\"分析最近30天各仓库的商品销量分布与商品销售情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"从ERP销售出库或销售单据明细中查询最近30天（按当前系统日期向前30天）的仓库、商品及销售数量，按仓库和商品汇总销量；仅统计已生效或已完成且未作废的单据，销量口径为实际出库或销售数量。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的汇总结果，分析各仓库的总销量、商品销量排名、仓库间热销商品差异，并生成各仓库商品销量分布图表。\"}]}',NULL,'2026-10-16 02:21:29','2026-10-16 02:21:29',0),(2110798515413258241,2108252428142247938,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:22:37','2026-10-16 02:22:37',0),(2110798538737782786,2108252428142247938,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天内各仓库的商品销量数据，按仓库和商品聚合出库数量，包含仓库、商品、销量等字段，统计口径为已生效的出库/销售记录。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于前序查询结果，汇总各仓库总销量，计算各仓库内商品销量排名、占比及销量分布，并生成对比分析结果。\"}]}',NULL,'2026-10-16 02:22:43','2026-10-16 02:22:43',0),(2110798583923019777,2108252428142247938,1900000000000000001,'PLANNER',3,'{\"query\":\"看看哪些商品库存低于安全库存\"}',NULL,'2026-10-16 02:22:53','2026-10-16 02:22:53',0),(2110798610028367873,2108252428142247938,1900000000000000001,'PLANNER',4,'{\"title\":\"库存低于安全库存商品查询\",\"objective\":\"查询当前库存数量低于安全库存的商品列表\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询所有商品的当前库存数量和安全库存数量，筛选当前库存数量低于安全库存的商品。输出商品编码、商品名称、规格型号、单位、当前库存数量、安全库存数量、库存差额（安全库存-当前库存）以及库存最后更新时间（如可获得），按库存差额从大到小排序。\"}]}',NULL,'2026-10-16 02:23:00','2026-10-16 02:23:00',0),(2110798626189021187,2108252428142247938,1900000000000000001,'PLANNER',5,'{\"query\":\"看看哪些商品库存低于安全库存\"}',NULL,'2026-10-16 02:23:03','2026-10-16 02:23:03',0),(2110798661165322244,2108252428142247938,1900000000000000001,'PLANNER',6,'{\"title\":\"安全库存预警查询\",\"objective\":\"查询当前库存低于安全库存的商品\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询所有仓库中当前库存量低于对应安全库存量的商品，输出商品编码、商品名称、仓库、当前库存量、安全库存量及缺口数量，并按缺口数量从大到小排序。\"}]}',NULL,'2026-10-16 02:23:12','2026-10-16 02:23:12',0),(2110798710083489795,2108252428142247938,1900000000000000001,'PLANNER',7,'{\"query\":\"帮我规划一次供应商供货表现分析\"}',NULL,'2026-10-16 02:23:23','2026-10-16 02:23:23',0),(2110798770745708547,2108252428142247938,1900000000000000001,'PLANNER',8,'{\"title\":\"供应商供货表现分析规划\",\"objective\":\"分析供应商在指定周期内的供货表现，识别交付、质量或成本方面的差异。\",\"needs_clarification\":true,\"clarification_questions\":[{\"id\":\"analysis_period\",\"question\":\"本次供应商供货表现分析采用哪个统计周期？\",\"options\":[\"最近30天\",\"最近90天\",\"本年度\",\"上月\"]},{\"id\":\"evaluation_focus\",\"question\":\"供货表现分析重点关注哪些指标？\",\"options\":[\"交付及时率与数量差异\",\"质量合格率\",\"价格与成本\",\"综合表现（交付/质量/成本）\"]}],\"steps\":[]}',NULL,'2026-10-16 02:23:38','2026-10-16 02:23:38',0),(2110798863272054786,2110798851427340290,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:24:00','2026-10-16 02:24:00',0),(2110798897417883650,2110798851427340290,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量分布与重点商品\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天内各仓库、各商品的销量，时间范围为当前系统日期向前30天，统计指标为已确认销售出库的商品销售数量，按仓库和商品两个维度进行分组汇总。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的查询结果，计算各仓库的总销量，分析各商品在其所属仓库内的销量占比，识别各仓库销量排名靠前的商品，并生成汇总表与可视化图表。\"}]}',NULL,'2026-10-16 02:24:08','2026-10-16 02:24:08',0),(2110799444287991809,2110798851427340290,1900000000000000001,'PLANNER',3,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:26:18','2026-10-16 02:26:18',0),(2110799507630370818,2110798851427340290,1900000000000000001,'PLANNER',4,'{\"title\":\"最近30天各仓库商品销量分析计划\",\"objective\":\"分析最近30天各仓库的商品销量分布与排名\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询最近30天（以当前系统时间2026-10-16为基准）各仓库分商品的销售出库数量，按仓库和商品汇总，输出仓库、商品编码/名称、销售数量等结果；如系统中有销售金额字段可一并汇总。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于前序查询结果，计算各仓库销量合计、商品销量占比、仓库内销量排名及累计占比，输出各仓库商品销量分布和重点商品分析结果。\"}]}',NULL,'2026-10-16 02:26:34','2026-10-16 02:26:34',0),(2110802488241274881,2110800295060615170,1900000000000000001,'PLANNER',1,'{\"query\":\"分析最近 30 天各仓库的商品销量\"}',NULL,'2026-10-16 02:38:24','2026-10-16 02:38:24',0),(2110802527038586882,2110800295060615170,1900000000000000001,'PLANNER',2,'{\"title\":\"最近30天各仓库商品销量分析\",\"objective\":\"分析最近30天各仓库的商品销量情况\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"从ERP销售出库或订单明细数据中，查询最近30天（2026-09-16至2026-10-16）按仓库和商品维度的销量汇总，输出仓库、商品、销售数量。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1的查询结果，计算各仓库总销量及排名；识别每个仓库销量前10的商品及其占本仓库总销量的比例；生成仓库销量对比和各仓库商品销量分布所需的分析数据。\"}]}',NULL,'2026-10-16 02:38:33','2026-10-16 02:38:33',0),(2110803904016007170,2110803897502253057,1900000000000000001,'PLANNER',1,'{\"query\":\"帮我看看哪些商品库存低于安全库存，需要补货\"}',NULL,'2026-10-16 02:44:02','2026-10-16 02:44:02',0),(2110804042096689155,2110803897502253057,1900000000000000001,'PLANNER',2,'{\"title\":\"低库存商品补货分析\",\"objective\":\"找出库存低于安全库存的商品并给出补货建议。\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询并关联商品档案与库存数据，按商品和仓库维度获取商品编码、商品名称、规格型号、计量单位、仓库、安全库存、当前可用库存；筛选当前可用库存低于该商品在该仓库的安全库存的记录，并计算缺货数量=安全库存-当前可用库存。\"},{\"step\":2,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"基于步骤1结果，按商品汇总各缺货仓库的缺货数量，统计涉及仓库数，形成需补货商品清单，并按缺货总量从高到低排序；输出总建议补货量及分仓库补货明细，用于后续生成补货报告或订单。\"}]}',NULL,'2026-10-16 02:44:35','2026-10-16 02:44:35',0),(2110804297018097667,2110803074680471553,1900000000000000001,'PLANNER',1,'{\"query\":\"请分析库存情况，给出补货建议\"}',NULL,'2026-10-16 02:45:35','2026-10-16 02:45:35',0),(2110804384066682882,2110803074680471553,1900000000000000001,'PLANNER',2,'{\"title\":\"库存分析与补货建议规划\",\"objective\":\"分析当前库存状况并输出补货建议\",\"needs_clarification\":true,\"clarification_questions\":[{\"id\":\"demand_period\",\"question\":\"补货建议中的销量/出库需求使用哪个统计周期？\",\"options\":[\"最近30天\",\"最近60天\",\"上月\"]},{\"id\":\"replenish_policy\",\"question\":\"补货建议采用哪种测算口径？\",\"options\":[\"按未来30天预计需求补货\",\"补足到安全库存上限\",\"按日均销量和补货周期计算\"]}],\"steps\":[]}',NULL,'2026-10-16 02:45:56','2026-10-16 02:45:56',0),(2110804448226951170,2110803074680471553,1900000000000000001,'PLANNER',3,'{\"answer\":\"补货建议中的销量/出库需求使用哪个统计周期？\\n最近30天\\n\\n补货建议采用哪种测算口径？\\n按未来30天预计需求补货\"}',NULL,'2026-10-16 02:46:11','2026-10-16 02:46:11',0),(2110804559149514753,2110803074680471553,1900000000000000001,'PLANNER',4,'{\"title\":\"库存分析与未来30天补货建议\",\"objective\":\"基于最近30天出库需求与当前库存，测算各商品未来30天预计需求并给出补货建议\",\"needs_clarification\":false,\"clarification_questions\":[],\"steps\":[{\"step\":1,\"type\":\"SQL_QUERY\",\"instruction\":\"查询所有商品的当前库存余额，包含商品编码、商品名称、库存数量、可用库存数量、库存单位及是否停用状态，按商品汇总。\"},{\"step\":2,\"type\":\"SQL_QUERY\",\"instruction\":\"查询当前时间往前30天内所有出库/销售出库明细，按商品汇总出库总数量，并统计每个商品的有出库天数。\"},{\"step\":3,\"type\":\"SQL_QUERY\",\"instruction\":\"查询当前已审核未完成入库或未入库的采购订单在途数量，按商品汇总，作为补货时应扣除的已有供给。\"},{\"step\":4,\"type\":\"PYTHON_ANALYSIS\",\"instruction\":\"合并步骤1、2、3的结果，按商品计算最近30天日均出库量=出库总量/30，未来30天预计需求=日均出库量*30，净补货建议量=max(未来30天预计需求-当前可用库存-采购在途数量,0)，并输出库存满足度、缺口数量和建议补货量明细。\"}]}',NULL,'2026-10-16 02:46:38','2026-10-16 02:46:38',0);
