--
-- Table structure for table `supplier`
--

DROP TABLE IF EXISTS `supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier` (
  `id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_code` varchar(64) NOT NULL COMMENT '供应商编码',
  `supplier_name` varchar(200) NOT NULL COMMENT '供应商名称',
  `contact_name` varchar(100) NOT NULL DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(32) NOT NULL DEFAULT '' COMMENT '联系电话',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '地址',
  `payment_terms` varchar(100) NOT NULL DEFAULT '' COMMENT '付款条件',
  `overall_score` int DEFAULT NULL COMMENT '供应商综合评分，INT×100，NULL表示样本不足',
  `delivery_score` int DEFAULT NULL COMMENT '供应商交付评分，INT×100，NULL表示样本不足',
  `quality_score` int DEFAULT NULL COMMENT '供应商质量评分，INT×100，NULL表示样本不足',
  `price_score` int DEFAULT NULL COMMENT '供应商价格评分，INT×100，NULL表示样本不足',
  `service_score` int DEFAULT NULL COMMENT '人工服务评分，INT×100，NULL表示尚未人工设定',
  `service_score_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '当前人工服务评分原因；服务分为空时为空字符串',
  `avg_delivery_days` decimal(10,2) DEFAULT NULL COMMENT '最近180天完全入库订单的金额加权平均到货周期（天）',
  `score_basis_amount` bigint DEFAULT NULL COMMENT '近180天已确认样本金额（分），不足样本时为空',
  `score_status` varchar(16) NOT NULL DEFAULT 'NOT_READY' COMMENT '评分状态：NOT_READY 样本不足；READY 可参与评分',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用，0禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by_id` bigint DEFAULT NULL COMMENT '最后维护人ID',
  `updated_by_name` varchar(100) NOT NULL DEFAULT '' COMMENT '最后维护人姓名',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常，1删除',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_supplier_code` (`supplier_code`),
  KEY `idx_supplier_name` (`supplier_name`),
  KEY `idx_supplier_score` (`overall_score`),
  KEY `idx_supplier_deleted_status` (`deleted`,`status`),
  KEY `idx_supplier_score_ready` (`deleted`,`status`,`score_status`,`overall_score` DESC),
  CONSTRAINT `chk_supplier_score_basis_amount` CHECK ((`score_basis_amount` >= 0)),
  CONSTRAINT `chk_supplier_score_direct_cutover_complete` CHECK ((1 = 1)),
  CONSTRAINT `chk_supplier_score_range` CHECK ((((`overall_score` is null) or (`overall_score` between 0 and 10000)) and ((`delivery_score` is null) or (`delivery_score` between 0 and 10000)) and ((`quality_score` is null) or (`quality_score` between 0 and 10000)) and ((`price_score` is null) or (`price_score` between 0 and 10000)) and ((`service_score` is null) or (`service_score` between 0 and 10000)))),
  CONSTRAINT `chk_supplier_score_status` CHECK ((`score_status` in (_utf8mb4'NOT_READY',_utf8mb4'READY'))),
  CONSTRAINT `chk_supplier_service_score_reason` CHECK ((((`service_score` is null) and (`service_score_reason` = _utf8mb4'')) or ((`service_score` is not null) and (char_length(trim(`service_score_reason`)) > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商表';
/*!40101 SET character_set_client = @saved_cs_client */;

