--
-- Table structure for table `supplier_product`
--

DROP TABLE IF EXISTS `supplier_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_product` (
  `id` bigint NOT NULL COMMENT '供应商供货产品ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `product_id` bigint NOT NULL COMMENT '产品ID',
  `latest_purchase_price` bigint DEFAULT NULL COMMENT '由已确认入库事实维护的最近成交单价，单位分',
  `quoted_purchase_price` bigint DEFAULT NULL COMMENT '人工有效报价，单位分',
  `quoted_price_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '当前人工有效报价原因；报价为空时为空字符串',
  `quoted_price_updated_at` datetime DEFAULT NULL COMMENT '报价最近维护时间',
  `quote_valid_until` date DEFAULT NULL COMMENT '报价有效截止日',
  `min_order_qty` bigint NOT NULL DEFAULT '0' COMMENT '最小起订量，放大100倍保存，1000表示10.00',
  `quality_score` int DEFAULT NULL COMMENT '供应产品质量评分，INT×100，NULL表示样本不足',
  `price_score` int DEFAULT NULL COMMENT '供应产品价格评分，INT×100，NULL表示样本不足',
  `recommend_score` int DEFAULT NULL COMMENT '供应产品推荐评分，INT×100，NULL表示样本不足',
  `last_purchase_at` datetime DEFAULT NULL COMMENT '当前最近成交价对应的最后一次已确认采购入库时间',
  `avg_delivery_days` decimal(10,2) DEFAULT NULL COMMENT '最近180天完全入库采购单的金额加权平均到货周期（天），仅供分析',
  `score_basis_amount` bigint DEFAULT NULL COMMENT '近180天已确认样本金额（分），不足样本时为空',
  `score_status` varchar(16) NOT NULL DEFAULT 'NOT_READY' COMMENT '评分状态：NOT_READY 样本不足；READY 可参与评分',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用，0禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by_id` bigint DEFAULT NULL COMMENT '最后维护人ID',
  `updated_by_name` varchar(100) NOT NULL DEFAULT '' COMMENT '最后维护人姓名',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常，1删除',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_supplier_product` (`supplier_id`,`product_id`),
  KEY `idx_supplier_product_product` (`product_id`),
  KEY `idx_supplier_product_deleted_status` (`deleted`,`status`),
  KEY `idx_supplier_product_ready` (`product_id`,`deleted`,`status`,`score_status`,`recommend_score` DESC),
  KEY `idx_supplier_product_quote_valid` (`product_id`,`deleted`,`status`,`quote_valid_until`),
  CONSTRAINT `chk_supplier_product_quote` CHECK ((((`quoted_purchase_price` is null) and (`quoted_price_reason` = _utf8mb4'') and (`quoted_price_updated_at` is null) and (`quote_valid_until` is null)) or ((`quoted_purchase_price` > 0) and (char_length(trim(`quoted_price_reason`)) > 0) and (`quoted_price_updated_at` is not null) and (`quote_valid_until` is not null)))),
  CONSTRAINT `chk_supplier_product_score_basis_amount` CHECK ((`score_basis_amount` >= 0)),
  CONSTRAINT `chk_supplier_product_score_range` CHECK ((((`quality_score` is null) or (`quality_score` between 0 and 10000)) and ((`price_score` is null) or (`price_score` between 0 and 10000)) and ((`recommend_score` is null) or (`recommend_score` between 0 and 10000)))),
  CONSTRAINT `chk_supplier_product_score_status` CHECK ((`score_status` in (_utf8mb4'NOT_READY',_utf8mb4'READY')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商供货产品表';
/*!40101 SET character_set_client = @saved_cs_client */;

